"""Versioned SDL source descriptors and the reversible SDL XSD profile.

Only the YAML paths import a third-party module. All readers populate the same
MsgParser model; name resolution and wire validation remain in generator.py.
"""

import copy
import io
import json
import math
import os
import re
import xml.etree.ElementTree as ET


SOURCE_SUFFIXES = ('.sdl.json', '.sdl.yaml', '.sdl.yml', '.sdl.xsd', '.sdl')
MARKERS = {
   'sdl': '// Generated by SDL compiler.',
   'json': '{"generated_by": "sdlc",',
   'yaml': '# Generated by SDL compiler.',
   'xsd': '<!-- Generated by SDL compiler. -->',
}
XS = 'http://www.w3.org/2001/XMLSchema'
SDL = 'urn:sdl:schema:1'
PRIMITIVES = {
   'bool': 'boolean', 'string': 'string',
   'int8': 'byte', 'int16': 'short', 'int32': 'int', 'int64': 'long',
   'uint8': 'unsignedByte', 'uint16': 'unsignedShort',
   'uint32': 'unsignedInt', 'uint64': 'unsignedLong',
   'fl32': 'float', 'fl64': 'double',
}


def _object(value, allowed, required=(), label='object'):
   if not isinstance(value, dict) or any(not isinstance(key, str) for key in value):
      raise ValueError(label + ' must be an object with string keys')
   unknown, missing = set(value) - set(allowed), set(required) - set(value)
   if unknown or missing:
      raise ValueError(label + ': ' + ('unknown keys ' + ', '.join(sorted(unknown))
         if unknown else 'missing keys ' + ', '.join(sorted(missing))))
   return value


def _text(value, label):
   if not isinstance(value, str):
      raise ValueError(label + ' must be a string')
   return value


def _integer(value, label):
   if type(value) is not int:
      raise ValueError(label + ' must be an integer')
   return value


def _list(value, label):
   if not isinstance(value, list):
      raise ValueError(label + ' must be an array')
   return value


def _mapping(value, label):
   if not isinstance(value, dict) or any(not isinstance(key, str) for key in value):
      raise ValueError(label + ' must be an object with string keys')
   return value


def _json_value(value, active=None, depth=0):
   """Reject YAML-specific objects, recursive aliases and non-finite numbers."""
   if depth > 64:
      raise ValueError('schema document nesting exceeds 64 levels')
   if value is None or type(value) in (str, int, bool):
      return
   if type(value) is float and math.isfinite(value):
      return
   if not isinstance(value, (dict, list)):
      raise ValueError('schema values must be JSON-compatible and finite')
   active = set() if active is None else active
   if id(value) in active:
      raise ValueError('recursive YAML aliases are not supported')
   active.add(id(value))
   if isinstance(value, dict):
      for key in value:
         _text(key, 'mapping key')
      values = value.values()
   else:
      values = value
   for child in values:
      _json_value(child, active, depth + 1)
   active.remove(id(value))


def _pairs(items):
   result = {}
   for key, value in items:
      if key in result:
         raise ValueError('duplicate mapping key: ' + key)
      result[key] = value
   return result


def _json_load(text):
   def invalid(value):
      raise ValueError('non-finite JSON number: ' + value)
   try:
      value = json.loads(text, object_pairs_hook=_pairs, parse_constant=invalid)
   except json.JSONDecodeError as error:
      raise ValueError('invalid JSON: ' + str(error)) from error
   _json_value(value)
   return value


def yaml_module():
   try:
      import yaml
   except ImportError as error:
      raise ValueError('YAML support requires PyYAML; install with '
         'python3 -m pip install PyYAML') from error
   return yaml


def _yaml_load(text):
   yaml = yaml_module()

   class Loader(yaml.SafeLoader):
      pass

   # Keep unquoted ON/OFF, dates, and leading-zero identifiers as text. Use
   # JSON-compatible scalar resolution rather than PyYAML's YAML 1.1 defaults.
   Loader.yaml_implicit_resolvers = copy.deepcopy(Loader.yaml_implicit_resolvers)
   tags = ('bool', 'int', 'float', 'timestamp', 'null')
   for key, resolvers in Loader.yaml_implicit_resolvers.items():
      Loader.yaml_implicit_resolvers[key] = [(tag, pattern) for tag, pattern in resolvers
         if tag.rsplit(':', 1)[-1] not in tags]
   for tag, pattern, initials in (
         ('bool', r'(?:true|false)\Z', 'tf'),
         ('null', r'null\Z', 'n'),
         ('int', r'-?(?:0|[1-9][0-9]*)\Z', '-0123456789'),
         ('float', r'-?(?:0|[1-9][0-9]*)(?:\.[0-9]+(?:[eE][+-]?[0-9]+)?|[eE][+-]?[0-9]+)\Z', '-0123456789')):
      Loader.add_implicit_resolver('tag:yaml.org,2002:' + tag, re.compile(pattern), list(initials))

   def mapping(loader, node):
      result = {}
      for key_node, value_node in node.value:
         key = loader.construct_object(key_node, deep=True)
         _text(key, 'YAML mapping key')
         if key in result:
            raise ValueError('duplicate mapping key: ' + key)
         result[key] = loader.construct_object(value_node, deep=True)
      return result

   Loader.add_constructor('tag:yaml.org,2002:map', mapping)
   try:
      value = yaml.load(text, Loader=Loader)
   except yaml.YAMLError as error:
      raise ValueError('invalid YAML: ' + str(error)) from error
   _json_value(value)
   return value


def _name(value, label, reference=False, anonymous=False):
   _text(value, label)
   pattern = r'\w+(?:\$[1-9][0-9]*)?' if anonymous else r'\w+'
   if reference:
      pattern = r'\.?(?:[^\W\d]\w*\.)*' + pattern
   if not re.fullmatch(pattern, value):
      raise ValueError('invalid ' + label + ': ' + value)
   return value


def load_document(document, schema, api):
   _json_value(document)
   _object(document, ('format', 'version', 'package', 'doc', 'constants', 'aliases',
      'enums', 'messages', 'generated_by'), ('format',), 'schema')
   version = document.get('version', 1)
   if document['format'] != 'sdl-schema' or type(version) is not int or version != 1:
      raise ValueError('expected sdl-schema format version 1')
   if 'generated_by' in document and document['generated_by'] != 'sdlc':
      raise ValueError('unknown generated_by marker')
   package = _text(document.get('package', ''), 'package')
   if package and not re.fullmatch(r'[A-Za-z][A-Za-z0-9_]*(?:\.[A-Za-z][A-Za-z0-9_]*)*', package):
      raise ValueError('invalid package: ' + package)
   schema.package = package
   schema.doc = _text(document.get('doc', ''), 'schema doc')
   declared = set()

   def declaration(name, anonymous=False, identifier=False):
      _name(name, 'declaration name', reference=True, anonymous=anonymous)
      if name.startswith('.'):
         raise ValueError('declaration names cannot start with a dot: ' + name)
      local = name
      if '.' in name:
         prefix, local = name.rsplit('.', 1)
         if prefix != package:
            raise ValueError('declaration is outside its package: ' + name)
      if identifier and not re.fullmatch(r'[^\W\d]\w*', local):
         raise ValueError('invalid declaration name: ' + name)
      full = package + '.' + local if package else local
      if full in declared:
         raise ValueError('duplicate declaration name: ' + full)
      if local in api.MsgParser.BUILTINS:
         raise ValueError('declaration name conflicts with built-in type: ' + local)
      declared.add(full)
      return name

   for name, item in _mapping(document.get('constants', {}), 'constants').items():
      declaration(name, identifier=True)
      _object(item, ('value', 'doc'), ('value',), 'constant ' + name)
      schema.constants[name] = _integer(item['value'], 'constant value')
      schema.constant_docs[name] = _text(item.get('doc', ''), 'constant doc')
   for name, item in _mapping(document.get('aliases', {}), 'aliases').items():
      declaration(name, identifier=True)
      _object(item, ('target', 'doc'), ('target',), 'alias ' + name)
      alias = api.Alias(name, _name(item['target'], 'alias target', reference=True, anonymous=True))
      alias.doc = _text(item.get('doc', ''), 'alias doc')
      schema.aliases[name] = alias
   for name, item in _mapping(document.get('enums', {}), 'enums').items():
      declaration(name)
      _object(item, ('values', 'doc'), ('values',), 'enum ' + name)
      enum = api.Enum(name)
      enum.doc = _text(item.get('doc', ''), 'enum doc')
      for value in _list(item['values'], 'enum values'):
         _object(value, ('name', 'value', 'doc'), ('name', 'value'), 'enum value')
         key = _name(value['name'], 'enum label')
         enum.pairs.append((key, str(_integer(value['value'], 'enum value'))))
         enum.value_docs[key] = _text(value.get('doc', ''), 'enum value doc')
      schema.enums[name] = enum
   for name, item in _mapping(document.get('messages', {}), 'messages').items():
      declaration(name, anonymous=True)
      _object(item, ('fields', 'doc'), ('fields',), 'message ' + name)
      message = api.Message(name)
      message.doc = _text(item.get('doc', ''), 'message doc')
      for value in _list(item['fields'], 'message fields'):
         _object(value, ('id', 'name', 'type', 'modifier', 'dimensions', 'wire', 'doc'),
            ('name', 'type'), 'field')
         index = _integer(value['id'], 'field id') if 'id' in value else schema._field_index(message, None)
         modifier = _text(value.get('modifier', 'required'), 'field modifier')
         if modifier not in ('required', 'optional', 'repeated', 'packed'):
            raise ValueError('unknown field modifier: ' + modifier)
         dimensions = _list(value.get('dimensions', []), 'field dimensions')
         for dimension in dimensions:
            if isinstance(dimension, str):
               _name(dimension, 'dimension constant reference', reference=True)
            else:
               _integer(dimension, 'dimension')
         wire = _object(value.get('wire', {}), api.WIRE_KEYS, label='wire options')
         for key, option in wire.items():
            if key in ('q', 'encoding'):
               if key == 'q' and type(option) in (int, float):
                  continue
               _text(option, 'wire ' + key)
            else:
               _integer(option, 'wire ' + key)
         normalized_wire = {}
         for key, option in wire.items():
            parsed = api.parse_wire_options(key + '=' + str(option))
            if set(parsed) != {key}:
               raise ValueError('invalid wire option value: ' + key)
            normalized_wire.update(parsed)
         wire = normalized_wire
         field = api.Field(index, modifier,
            _name(value['type'], 'field type', reference=True, anonymous=True),
            _name(value['name'], 'field name'), list(dimensions), wire)
         field.doc = _text(value.get('doc', ''), 'field doc')
         message.fields.append(field)
      schema.messages[name] = message
      schema.message_order.append(name)
   schema._qualify_types()


def _reference(name, builtins):
   # Explicit dot protects global references when reading a packaged unit.
   return '.' + name if '.' not in name and name not in builtins else name


def _message_document(message, builtins):
   return {'doc': message.doc, 'fields': [dict(
      id=field.index, name=field.name, type=_reference(field.type_name, builtins),
      modifier=field.modifier, dimensions=list(field.array_dimensions),
      wire=dict(field.wire), doc=field.doc) for field in message.fields]}


def _enum_document(enum):
   return {'doc': enum.doc, 'values': [dict(name=name, value=int(value),
      doc=enum.value_docs.get(name, '')) for name, value in enum.pairs]}


def schema_document(schema):
   return dict(format='sdl-schema', version=1, package=schema.package, doc=schema.doc,
      constants={name: dict(value=value, doc=schema.constant_docs.get(name, ''))
         for name, value in schema.constants.items()},
      aliases={name: dict(target=_reference(alias.target, schema.BUILTINS), doc=alias.doc)
         for name, alias in schema.aliases.items()},
      enums={name: _enum_document(enum) for name, enum in schema.enums.items()},
      messages={name: _message_document(message, schema.BUILTINS) for name, message in schema.messages.items()})


def _without_empty_doc(item):
   return {key: value for key, value in item.items() if key != 'doc' or value != ''}


def _compact_field(field, previous_id):
   result = _without_empty_doc(field)
   for key, default in (('id', previous_id + 1), ('modifier', 'required'),
         ('dimensions', []), ('wire', {})):
      if key in result and result[key] == default:
         del result[key]
   return result


def compact_document(document):
   """Omit source defaults without changing IDs, declarations or wire metadata."""
   result = _without_empty_doc(document)
   if type(result.get('version')) is int and result['version'] == 1:
      del result['version']
   if result.get('package') == '':
      del result['package']
   for key in ('constants', 'aliases', 'enums', 'messages'):
      if key not in result:
         continue
      if not result[key]:
         del result[key]
         continue
      declarations = {}
      for name, item in result[key].items():
         item = _without_empty_doc(item)
         if key == 'enums':
            item['values'] = [_without_empty_doc(value) for value in item['values']]
         elif key == 'messages':
            fields, previous_id = [], 0
            for field in item['fields']:
               fields.append(_compact_field(field, previous_id))
               previous_id = field.get('id', previous_id + 1)
            item['fields'] = fields
         declarations[name] = item
      result[key] = declarations
   return result


def sdl_text(schema):
   """Reconstruct normalized textual SDL and check that no metadata was lost."""
   from generator import WIRE_KEYS
   lines = []

   def documentation(text, indent=''):
      if not text:
         return
      if '*/' in text:
         raise ValueError('SDL documentation cannot contain a closing comment delimiter')
      lines.append(indent + '/**')
      lines.extend(indent + ' * ' + line for line in text.split('\n'))
      lines.append(indent + ' */')

   def reference(name):
      if '$' in name:
         raise ValueError('anonymous types cannot be referenced by name in textual SDL: ' + name)
      if schema.package and '.' in name and name.rsplit('.', 1)[0] == schema.package:
         return name.rsplit('.', 1)[-1]
      return _reference(name, schema.BUILTINS)

   def fields(message, indent):
      previous_id = 0
      for field in message.fields:
         documentation(field.doc, indent)
         prefix = '' if field.index == previous_id + 1 else str(field.index) + ': '
         previous_id = field.index
         if field.modifier != 'required':
            prefix += field.modifier + ' '
         wire = ' wire(' + ','.join(key + '=' + str(field.wire[key])
            for key in WIRE_KEYS if key in field.wire) + ')' if field.wire else ''
         if '$' in field.type_name and dict.__contains__(schema.messages, field.type_name):
            if field.array_dimensions:
               raise ValueError('textual SDL cannot attach dimensions to an anonymous struct')
            lines.append(indent + prefix + 'struct {')
            fields(schema.messages[field.type_name], indent + '   ')
            lines.append(indent + '} ' + field.name + wire + ';')
         else:
            dimensions = ''.join('[' + str(value) + ']' for value in field.array_dimensions)
            lines.append(indent + prefix + reference(field.type_name) + dimensions + ' ' + field.name + wire + ';')

   if schema.doc and not schema.package:
      raise ValueError('textual SDL module documentation requires a package declaration')
   documentation(schema.doc)
   if schema.package:
      lines.extend(['package ' + schema.package + ';', ''])
   for name, value in schema.constants.items():
      documentation(schema.constant_docs.get(name, ''))
      lines.extend(['const ' + name.rsplit('.', 1)[-1] + ' = ' + str(value) + ';', ''])
   for name, alias in schema.aliases.items():
      documentation(alias.doc)
      lines.extend(['alias ' + name.rsplit('.', 1)[-1] + ' = ' + reference(alias.target) + ';', ''])
   for name, enum in schema.enums.items():
      documentation(enum.doc)
      lines.append('enum ' + name.rsplit('.', 1)[-1] + ' {')
      for key, value in enum.pairs:
         documentation(enum.value_docs.get(key, ''), '   ')
         lines.append('   ' + key + ' = ' + str(value) + ';')
      lines.extend(['}', ''])
   for name, message in schema.messages.items():
      if '$' in name:
         continue
      documentation(message.doc)
      lines.append('message ' + name.rsplit('.', 1)[-1] + ' {')
      fields(message, '   ')
      lines.extend(['}', ''])
   text = '\n'.join(lines)
   restored = type(schema)()
   restored.parse_text(text, validate=False)
   if schema_document(restored) != schema_document(schema):
      raise ValueError('schema cannot be represented losslessly as textual SDL: ' + schema.base_name)
   return text


def xml_name(name):
   """Injective mapping into ASCII NCNames, including qualified/anonymous SDL names."""
   if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_.-]*', name) and not name.startswith('_sdl_'):
      return name
   return '_sdl_' + name.encode('utf-8').hex()


def _tag(name):
   return '{' + XS + '}' + name


def _annotation(element, kind, metadata, doc=''):
   annotation = ET.SubElement(element, _tag('annotation'))
   if doc:
      ET.SubElement(annotation, _tag('documentation')).text = doc
   info = ET.SubElement(annotation, _tag('appinfo'))
   ET.SubElement(info, '{' + SDL + '}' + kind).text = json.dumps(metadata, ensure_ascii=False, allow_nan=False)


def _xml_type(name):
   name = name.lstrip('.')
   if name in PRIMITIVES:
      return 'xs:' + PRIMITIVES[name]
   if name in ('c32', 'c64'):
      return '_sdl_builtin_' + name
   return xml_name(name)


def _collection(element, field, dimensions):
   if not dimensions:
      element.set('type', _xml_type(field['type']))
      return
   sequence = ET.SubElement(ET.SubElement(element, _tag('complexType')), _tag('sequence'))
   count = dimensions[0]
   item = ET.SubElement(sequence, _tag('element'), name='item')
   if count != 1:
      item.set('minOccurs', '0' if count == 'unbounded' else str(count))
      item.set('maxOccurs', str(count))
   _collection(item, field, dimensions[1:])


def xsd_tree(document, external_messages=None, external_enums=None):
   """Build one self-contained XSD, with ownership retained in SDL annotations."""
   root = ET.Element(_tag('schema'), elementFormDefault='unqualified')
   unit = {key: value for key, value in document.items()
      if key not in ('messages', 'enums', 'doc', 'generated_by')}
   _annotation(root, 'unit', compact_document(unit), document.get('doc', ''))
   messages = dict(external_messages or {})
   messages.update(document.get('messages', {}))
   enums = dict(external_enums or {})
   enums.update(document.get('enums', {}))
   used = {field['type'].lstrip('.') for message in messages.values() for field in message['fields']}
   for builtin in ('c32', 'c64'):
      if builtin not in used:
         continue
      complex_type = ET.SubElement(root, _tag('complexType'), name='_sdl_builtin_' + builtin)
      sequence = ET.SubElement(complex_type, _tag('sequence'))
      for part in ('real', 'imag'):
         ET.SubElement(sequence, _tag('element'), name=part,
            type='xs:float' if builtin == 'c32' else 'xs:double')
   for name, enum in enums.items():
      element = ET.SubElement(root, _tag('simpleType'), name=xml_name(name))
      values = [{key: value for key, value in item.items() if key != 'doc'} for item in enum['values']]
      _annotation(element, 'enum', dict(name=name, owned=name in document.get('enums', {}), values=values), enum.get('doc', ''))
      restriction = ET.SubElement(element, _tag('restriction'), base='xs:string')
      for value in enum['values']:
         facet = ET.SubElement(restriction, _tag('enumeration'), value=value['name'])
         if value.get('doc'):
            ET.SubElement(ET.SubElement(facet, _tag('annotation')), _tag('documentation')).text = value['doc']
   for name, message in messages.items():
      element = ET.SubElement(root, _tag('complexType'), name=xml_name(name))
      _annotation(element, 'message', dict(name=name, owned=name in document.get('messages', {})), message.get('doc', ''))
      sequence = ET.SubElement(element, _tag('sequence'))
      previous_id = 0
      for field in message['fields']:
         element = ET.SubElement(sequence, _tag('element'), name=xml_name(field['name']))
         if field['modifier'] == 'optional':
            element.set('minOccurs', '0')
         metadata = _compact_field({key: value for key, value in field.items() if key != 'doc'}, previous_id)
         _annotation(element, 'field', metadata, field.get('doc', ''))
         previous_id = field['id']
         dimensions = field['dimensions']
         if field['modifier'] in ('repeated', 'packed'):
            dimensions = ['unbounded']
         _collection(element, field, dimensions)
      ET.SubElement(root, _tag('element'), name=xml_name(name), type=xml_name(name))
   return root


def _xml_metadata(element, kind):
   values = element.findall('./' + _tag('annotation') + '/' + _tag('appinfo') + '/{' + SDL + '}' + kind)
   if len(values) != 1:
      raise ValueError('XSD profile requires exactly one sdl:' + kind + ' annotation')
   return _json_load(values[0].text or '')


def _xml_doc(element):
   value = element.find('./' + _tag('annotation') + '/' + _tag('documentation'))
   return value.text or '' if value is not None else ''


def _xml_signature(element):
   # Iterative traversal also handles SDL's maximum 255 fixed dimensions.
   result, pending, previous_id = [], [(element, None)], 0
   while pending:
      element, parent_tag = pending.pop()
      if element.tag == _tag('complexType') and 'name' in element.attrib:
         previous_id = 0
      text = element.text or ''
      if element.tag.startswith('{' + SDL + '}'):
         metadata = _json_load(text)
         if element.tag == '{' + SDL + '}unit':
            metadata = compact_document(metadata)
         elif element.tag == '{' + SDL + '}field':
            index = metadata.get('id', previous_id + 1)
            metadata = _compact_field(metadata, previous_id)
            previous_id = index
         text = json.dumps(metadata, sort_keys=True, ensure_ascii=False)
      elif element.tag != _tag('documentation'):
         text = text.strip()
      attributes = dict(element.attrib)
      if element.tag == _tag('element') and parent_tag == _tag('sequence'):
         for key in ('minOccurs', 'maxOccurs'):
            if attributes.get(key) == '1':
               del attributes[key]
      result.append((element.tag, sorted(attributes.items()), text,
         (element.tail or '').strip(), len(element)))
      pending.extend((child, element.tag) for child in reversed(element))
   return result


def _read_xsd(text, schema, api):
   if re.search(r'<!\s*(?:DOCTYPE|ENTITY)\b', text, re.I):
      raise ValueError('DOCTYPE and entity declarations are not supported in SDL XSD')
   try:
      iterator = ET.iterparse(io.StringIO(text), events=('start-ns', 'start', 'end'))
      bound_xs = False
      seen_root = False
      for event, value in iterator:
         if event == 'start' and not seen_root:
            if not bound_xs:
               raise ValueError('SDL XSD requires xs bound on the schema element')
            seen_root = True
         if event != 'start-ns':
            continue
         prefix, namespace = value
         if (prefix == 'xs' and namespace != XS) or (not prefix and namespace):
            raise ValueError('SDL XSD requires xs bound to XML Schema and no default namespace')
         bound_xs = bound_xs or prefix == 'xs'
      root = iterator.root
      if not bound_xs:
         raise ValueError('SDL XSD requires the xs namespace prefix')
   except ET.ParseError as error:
      raise ValueError('invalid XSD XML: ' + str(error)) from error
   if root.tag != _tag('schema') or root.get('targetNamespace'):
      raise ValueError('expected an SDL annotated XSD without targetNamespace')
   document = _xml_metadata(root, 'unit')
   _object(document, ('format', 'version', 'package', 'constants', 'aliases'), ('format',), 'XSD unit')
   document = dict(document, doc=_xml_doc(root), messages={}, enums={})
   external_messages, external_enums = {}, {}
   for element in root:
      kind = 'message' if element.tag == _tag('complexType') else 'enum'
      if element.tag not in (_tag('complexType'), _tag('simpleType')):
         continue
      if element.get('name') in ('_sdl_builtin_c32', '_sdl_builtin_c64'):
         continue
      metadata = _xml_metadata(element, kind)
      _object(metadata, ('name', 'owned', 'values') if kind == 'enum' else ('name', 'owned'),
         ('name', 'owned', 'values') if kind == 'enum' else ('name', 'owned'), 'XSD ' + kind)
      name = _name(metadata['name'], 'XSD type name', reference=True, anonymous=kind == 'message')
      if type(metadata['owned']) is not bool:
         raise ValueError('XSD owned must be boolean')
      target = document['messages' if kind == 'message' else 'enums'] if metadata['owned'] else (
         external_messages if kind == 'message' else external_enums)
      if any(name in table for table in (document['messages'], document['enums'], external_messages, external_enums)):
         raise ValueError('duplicate XSD declaration: ' + name)
      item = dict(doc=_xml_doc(element))
      if kind == 'message':
         fields = []
         for field in element.findall('./' + _tag('sequence') + '/' + _tag('element')):
            metadata_field = _xml_metadata(field, 'field')
            if not isinstance(metadata_field, dict):
               raise ValueError('XSD field annotation must be an object')
            fields.append(dict(metadata_field, doc=_xml_doc(field)))
         item['fields'] = fields
      else:
         facets = element.findall('./' + _tag('restriction') + '/' + _tag('enumeration'))
         values = _list(metadata['values'], 'XSD enum values')
         if len(values) != len(facets):
            raise ValueError('XSD enum facets disagree with SDL metadata')
         item['values'] = []
         for value, facet in zip(values, facets):
            _object(value, ('name', 'value'), ('name', 'value'), 'XSD enum value')
            item['values'].append(dict(value, doc=_xml_doc(facet)))
      target[name] = item
   # Validate metadata using the native reader before interpreting its structure.
   load_document(document, schema, api)
   for name, item in list(external_messages.items()) + list(external_enums.items()):
      package = name.rsplit('.', 1)[0] if '.' in name else ''
      key = 'messages' if name in external_messages else 'enums'
      dependency = api.MsgParser()
      load_document(dict(format='sdl-schema', version=1, package=package, **{key: {name: item}}), dependency, api)
      if key == 'messages':
         external_messages[name] = _message_document(dependency.messages[name], schema.BUILTINS)
      else:
         external_enums[name] = _enum_document(dependency.enums[name])
   schema.xsd_dependencies = (external_messages, external_enums)
   schema.xsd_signature = _xml_signature(root)


def validate_xsd_dependencies(schema):
   if not hasattr(schema, 'xsd_dependencies'):
      return
   messages, enums = schema.xsd_dependencies
   actual_messages, actual_enums = schema.catalogue_types()
   expected_messages = {name: _message_document(message, schema.BUILTINS)
      for name, message in actual_messages.items() if not dict.__contains__(schema.messages, name)}
   expected_enums = {name: _enum_document(enum) for name, enum in actual_enums.items()
      if not dict.__contains__(schema.enums, name)}
   if messages != expected_messages or enums != expected_enums:
      raise ValueError('XSD dependency copies disagree with resolved SDL sources in ' + schema.base_name)
   expected = xsd_tree(schema_document(schema), expected_messages, expected_enums)
   if schema.xsd_signature != _xml_signature(expected):
      raise ValueError('unsupported XSD construction or XML structure disagrees with SDL annotations in ' + schema.base_name)


def read_schema(path, schema, api):
   with open(path, 'r', encoding='utf-8') as source:
      text = source.read()
   if path.endswith('.sdl.json'):
      load_document(_json_load(text), schema, api)
   elif path.endswith(('.sdl.yaml', '.sdl.yml')):
      load_document(_yaml_load(text), schema, api)
   elif path.endswith('.sdl.xsd'):
      _read_xsd(text, schema, api)
   else:
      schema.parse_text(text, validate=False)


def _xml_text(root):
   ET.register_namespace('xs', XS)
   ET.register_namespace('sdl', SDL)
   ET.indent(root, space='  ')
   text = ET.tostring(root, encoding='unicode').replace('\r', '&#13;')
   # ElementTree escapes markup but XML 1.0 cannot carry all Unicode scalars.
   if any(not (ch in '\t\n\r' or 0x20 <= ord(ch) <= 0xD7FF or
         0xE000 <= ord(ch) <= 0xFFFD or 0x10000 <= ord(ch) <= 0x10FFFF) for ch in text):
      raise ValueError('XSD documentation contains characters forbidden by XML 1.0')
   return text


def generate_schema_formats(input_path, output_dir, formats):
   from generator import parse_schemas, clear_generated_outputs
   schemas = parse_schemas(input_path)
   outputs = []
   for base, _, schema in schemas:
      document = schema_document(schema)
      relative = os.path.join(*schema.package.split('.'), base) if schema.package else base
      for kind in formats:
         if kind == 'sdl':
            text = MARKERS[kind] + '\n' + sdl_text(schema)
         elif kind == 'json':
            text = MARKERS[kind] + '\n' + json.dumps(compact_document(document), indent=2, ensure_ascii=False, allow_nan=False)[2:] + '\n'
         elif kind == 'yaml':
            text = MARKERS[kind] + '\n' + yaml_module().safe_dump(compact_document(document),
               sort_keys=False, allow_unicode=True)
         else:
            messages, enums = schema.catalogue_types()
            messages = {name: _message_document(message, schema.BUILTINS) for name, message in messages.items()
               if not dict.__contains__(schema.messages, name)}
            enums = {name: _enum_document(enum) for name, enum in enums.items()
               if not dict.__contains__(schema.enums, name)}
            text = MARKERS[kind] + '\n' + _xml_text(xsd_tree(document, messages, enums)) + '\n'
         suffix = '.sdl' if kind == 'sdl' else '.sdl.' + kind
         outputs.append((kind, relative + suffix, text))
   # Serialize everything before removing any stale exports.
   for kind in formats:
      suffix = '.sdl' if kind == 'sdl' else '.sdl.' + kind
      clear_generated_outputs(os.path.join(output_dir, kind), (suffix,), (MARKERS[kind],))
   for kind, relative, text in outputs:
      path = os.path.join(output_dir, kind, relative)
      os.makedirs(os.path.dirname(path), exist_ok=True)
      with open(path, 'w', encoding='utf-8') as target:
         target.write(text)
